      <div class="countdown">
        <div class="label">Nog te gaan</div>
        <div class="time" id="time">--:--:--</div>
      </div>
      <div class="hand hour" id="hour"></div>
      <div class="hand minute" id="minute"></div>
      <div class="hand second" id="second"></div>
      <div class="center-dot"></div>
    </div>
  </div>
</div>

<div class="message" id="message"></div>

<script>
  const face = document.getElementById('face');
  const alarm = document.getElementById('alarm');
  const timeEl = document.getElementById('time');
  const message = document.getElementById('message');
  const hourHand = document.getElementById('hour');
  const minuteHand = document.getElementById('minute');
  const secondHand = document.getElementById('second');

  // Cijfers 1 t/m 12 op de wijzerplaat
  for (let i = 1; i <= 12; i++) {
    const n = document.createElement('div');
    n.className = 'num';
    const angle = (i / 12) * 2 * Math.PI;
    const r = 115; // straal van de cijfers
    const x = 50 + (r / 3) * Math.sin(angle); // in procenten van de plaat
    const y = 50 - (r / 3) * Math.cos(angle);
    n.textContent = i;
    n.style.left = x + '%';
    n.style.top = y + '%';
    face.appendChild(n);
  }

  // Het doel: 1 januari 00:00 van het volgende jaar
  function getTarget(now) {
    return new Date(now.getFullYear() + 1, 0, 1, 0, 0, 0);
  }

  function pad(n) { return String(n).padStart(2, '0'); }

  function update() {
    const now = new Date();

    // Wijzers van de echte tijd
    const sec = now.getSeconds() + now.getMilliseconds() / 1000;
    const min = now.getMinutes() + sec / 60;
    const hr = (now.getHours() % 12) + min / 60;
    secondHand.style.transform = `rotate(${sec * 6}deg)`;
    minuteHand.style.transform = `rotate(${min * 6}deg)`;
    hourHand.style.transform = `rotate(${hr * 30}deg)`;

    // Aftelling
    const target = getTarget(now);
    let diff = target - now;

    if (diff <= 0) {
      timeEl.textContent = '00:00:00:00';
      message.textContent = '🎉 Gelukkig Nieuwjaar! 🎉';
      alarm.classList.add('ring');
      return;
    }

    const days = Math.floor(diff / 86400000);
    diff %= 86400000;
    const hours = Math.floor(diff / 3600000);
    diff %= 3600000;
    const minutes = Math.floor(diff / 60000);
    diff %= 60000;
    const seconds = Math.floor(diff / 1000);

    timeEl.innerHTML = `${days}d ${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;
    message.textContent = '';
  }

  update();
  setInterval(update, 100);
</script>
</body>
</html>
