<script>
  // Maakt één kaart aan met bovenste en onderste helft plus de klapkaarten
  function createCard() {
    const c = document.createElement('div');
    c.className = 'card';
    c.innerHTML = `
      <div class="half top"><span></span></div>
      <div class="half bottom"><span></span></div>
      <div class="flap top"><span></span></div>
      <div class="flap bottom"><span></span></div>`;
    return c;
  }

  // Zet het cijfer direct op alle onderdelen (zonder animatie)
  function setAll(c, ch) {
    c.querySelectorAll('span').forEach(s => s.textContent = ch);
  }

  // Laat het cijfer wegklappen naar het nieuwe cijfer
  function setDigit(c, ch) {
    if (c.dataset.v === undefined) {
      setAll(c, ch);
      c.dataset.v = ch;
      return;
    }
    if (c.dataset.v === ch) return;

    const old = c.dataset.v;
    c.dataset.v = ch;

    const htop = c.querySelector('.half.top span');
    const hbot = c.querySelector('.half.bottom span');
    const ftop = c.querySelector('.flap.top');
    const fbot = c.querySelector('.flap.bottom');

    // Vaste onderdelen: boven = nieuw, onder = oud
    htop.textContent = ch;
    hbot.textContent = old;
    // Klapkaarten: boven = oud (valt naar beneden), onder = nieuw (klapt omhoog)
    ftop.querySelector('span').textContent = old;
    fbot.querySelector('span').textContent = ch;

    ftop.classList.remove('go');
    fbot.classList.remove('go');
    void c.offsetWidth; // forceer herstart van de animatie
    ftop.classList.add('go');
    fbot.classList.add('go');

    clearTimeout(c._timer);
    c._timer = setTimeout(() => {
      setAll(c, ch);
      ftop.classList.remove('go');
      fbot.classList.remove('go');
    }, 650);
  }

  // Maak de kaarten aan
  const groups = {
    days:    { el: document.getElementById('days'),    count: 3, cards: [] },
    hours:   { el: document.getElementById('hours'),   count: 2, cards: [] },
    minutes: { el: document.getElementById('minutes'), count: 2, cards: [] },
    seconds: { el: document.getElementById('seconds'), count: 2, cards: [] },
  };

  for (const key in groups) {
    const g = groups[key];
    for (let i = 0; i < g.count; i++) {
      const card = createCard();
      g.el.appendChild(card);
      g.cards.push(card);
    }
  }

  const message = document.getElementById('message');

  function getTarget(now) {
    return new Date(now.getFullYear() + 1, 0, 1, 0, 0, 0);
  }

  function showValue(group, value) {
    const str = String(value).padStart(group.count, '0');
    group.cards.forEach((card, i) => setDigit(card, str[i]));
  }

  function update() {
    const now = new Date();
    let diff = getTarget(now) - now;

    if (diff <= 0) {
      showValue(groups.days, 0);
      showValue(groups.hours, 0);
      showValue(groups.minutes, 0);
      showValue(groups.seconds, 0);
      message.textContent = '🎉 Gelukkig Nieuwjaar! 🎉';
      return;
    }

    const days = Math.floor(diff / 86400000);
    diff %= 86400000;
    const hours = Math.floor(diff / 3600000);
    diff %= 3600000;
    const minutes = Math.floor(diff / 60000);
    diff %= 60000;
    const seconds = Math.floor(diff / 1000);

    showValue(groups.days, days);
    showValue(groups.hours, hours);
    showValue(groups.minutes, minutes);
    showValue(groups.seconds, seconds);
    message.textContent = '';
  }

  update();
  setInterval(update, 250);
</script>
</body>
</html>
